package frame

import (
	"bytes"
	"encoding/hex"
	"errors"
	"strings"
	"testing"
)

// goldenNodeID is easy to spot in a hexdump: 00 11 22 ... ff.
var goldenNodeID = NodeID{
	0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77,
	0x88, 0x99, 0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff,
}

// goldenFrame is a span frame, compressed with zstd, carrying the payload "hi".
// The bytes were written by hand from SPEC.md §3.2, not generated by Encode, so
// the test catches the encoder and the spec disagreeing.
const goldenHex = "" +
	"4f" + // Magic 'O'
	"01" + // Version 1
	"03" + // DataType span
	"03" + // Flags compressed|zstd
	"00112233445566778899aabbccddeeff" + // NodeID
	"00000002" + // PayloadLen 2, big-endian
	"6869" // Payload "hi"

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad hex in test: %v", err)
	}
	return b
}

func TestEncodeGolden(t *testing.T) {
	got, err := Encode(Header{
		DataType: DataTypeSpan,
		Flags:    FlagCompressed | FlagZstd,
		NodeID:   goldenNodeID,
	}, []byte("hi"))
	if err != nil {
		t.Fatalf("Encode: %v", err)
	}
	if want := mustHex(t, goldenHex); !bytes.Equal(got, want) {
		t.Errorf("Encode mismatch\n got  %x\n want %x", got, want)
	}
}

func TestDecodeGolden(t *testing.T) {
	fr, err := Decode(mustHex(t, goldenHex))
	if err != nil {
		t.Fatalf("Decode: %v", err)
	}
	if fr.DataType != DataTypeSpan {
		t.Errorf("DataType = %v, want span", fr.DataType)
	}
	if fr.Flags != FlagCompressed|FlagZstd {
		t.Errorf("Flags = %v, want compressed|zstd", fr.Flags)
	}
	if fr.NodeID != goldenNodeID {
		t.Errorf("NodeID = %v, want %v", fr.NodeID, goldenNodeID)
	}
	if fr.PayloadLen != 2 {
		t.Errorf("PayloadLen = %d, want 2", fr.PayloadLen)
	}
	if string(fr.Payload) != "hi" {
		t.Errorf("Payload = %q, want \"hi\"", fr.Payload)
	}
}

func TestRoundTrip(t *testing.T) {
	tests := []struct {
		name    string
		dt      DataType
		flags   Flags
		payload []byte
	}{
		{"log, no flags, empty payload", DataTypeLog, 0, nil},
		{"metric, gzip", DataTypeMetric, FlagCompressed, []byte("gauge")},
		{"span, zstd", DataTypeSpan, FlagCompressed | FlagZstd, bytes.Repeat([]byte{0xab}, 100)},
		{"span, sealed", DataTypeSpan, FlagSealed, []byte("ciphertext")},
		{"span, max payload", DataTypeSpan, 0, bytes.Repeat([]byte{1}, DefaultMaxPayload)},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			in := Header{DataType: tc.dt, Flags: tc.flags, NodeID: goldenNodeID}
			b, err := Encode(in, tc.payload)
			if err != nil {
				t.Fatalf("Encode: %v", err)
			}
			if len(b) != HeaderSize+len(tc.payload) {
				t.Fatalf("encoded length = %d, want %d", len(b), HeaderSize+len(tc.payload))
			}
			fr, err := Decode(b)
			if err != nil {
				t.Fatalf("Decode: %v", err)
			}
			in.PayloadLen = uint32(len(tc.payload))
			if fr.Header != in {
				t.Errorf("Header = %+v, want %+v", fr.Header, in)
			}
			if !bytes.Equal(fr.Payload, tc.payload) {
				t.Errorf("Payload mismatch")
			}
		})
	}
}

// TestDecodePayloadIsCopy guards the promise in DecodeLimit's doc comment: a
// caller may overwrite the input buffer and the decoded payload must not change.
func TestDecodePayloadIsCopy(t *testing.T) {
	b := mustHex(t, goldenHex)
	fr, err := Decode(b)
	if err != nil {
		t.Fatal(err)
	}
	b[HeaderSize] = 'X'
	if string(fr.Payload) != "hi" {
		t.Errorf("Payload aliased the input buffer: %q", fr.Payload)
	}
}

func TestDecodeErrors(t *testing.T) {
	golden := mustHex(t, goldenHex)

	// mutate returns a copy of golden with one byte changed.
	mutate := func(off int, v byte) []byte {
		b := bytes.Clone(golden)
		b[off] = v
		return b
	}

	tests := []struct {
		name string
		in   []byte
		want error
	}{
		{"empty", nil, ErrTooShort},
		{"23 bytes", golden[:23], ErrTooShort},
		{"bad magic", mutate(0, 'X'), ErrBadMagic},
		{"version 2", mutate(1, 0x02), ErrVersion},
		{"data type 0", mutate(2, 0x00), ErrDataType},
		{"data type 4", mutate(2, 0x04), ErrDataType},
		{"reserved bit 7", mutate(3, 0x80), ErrReservedFlags},
		{"reserved bit 3", mutate(3, 0x08), ErrReservedFlags},
		{"zstd without compressed", mutate(3, 0x02), ErrZstdWithoutCompression},
		{"truncated payload", golden[:len(golden)-1], ErrLength},
		{"trailing byte", append(bytes.Clone(golden), 0), ErrLength},
		{"PayloadLen says 3, have 2", mutate(23, 0x03), ErrLength},
		{"PayloadLen 0xFFFFFFFF", append(mutate(20, 0xff), 0), ErrPayloadTooLarge},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := Decode(tc.in)
			if !errors.Is(err, tc.want) {
				t.Errorf("Decode error = %v, want %v", err, tc.want)
			}
		})
	}
}

func TestDecodeLimit(t *testing.T) {
	b, err := Encode(Header{DataType: DataTypeSpan, NodeID: goldenNodeID}, make([]byte, 300))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := DecodeLimit(b, 256); !errors.Is(err, ErrPayloadTooLarge) {
		t.Errorf("limit 256: error = %v, want ErrPayloadTooLarge", err)
	}
	if _, err := DecodeLimit(b, 300); err != nil {
		t.Errorf("limit 300: unexpected error %v", err)
	}
}

func TestEncodeRejectsBadHeader(t *testing.T) {
	if _, err := Encode(Header{DataType: 0x09}, nil); !errors.Is(err, ErrDataType) {
		t.Errorf("bad data type: error = %v", err)
	}
	if _, err := Encode(Header{DataType: DataTypeSpan, Flags: 0x40}, nil); !errors.Is(err, ErrReservedFlags) {
		t.Errorf("reserved flag: error = %v", err)
	}
}

func TestStrings(t *testing.T) {
	if got, want := goldenNodeID.String(), "00112233-4455-6677-8899-aabbccddeeff"; got != want {
		t.Errorf("NodeID.String() = %q, want %q", got, want)
	}
	if got := (FlagCompressed | FlagZstd | FlagSealed).String(); got != "compressed|zstd|sealed" {
		t.Errorf("Flags.String() = %q", got)
	}
	if got := Flags(0).String(); got != "none" {
		t.Errorf("Flags(0).String() = %q", got)
	}
	if got := DataType(0x42).String(); !strings.Contains(got, "unknown") {
		t.Errorf("DataType(0x42).String() = %q", got)
	}
}

// FuzzDecode feeds random bytes to Decode. Two properties must hold:
//  1. Decode never panics, whatever the input (the fuzzer checks this for us).
//  2. If Decode accepts the input, Encode(result) reproduces it byte for byte.
//
// Run with: go test -fuzz=FuzzDecode -fuzztime=30s ./pkg/frame
func FuzzDecode(f *testing.F) {
	golden, _ := hex.DecodeString(goldenHex)
	f.Add(golden)
	f.Add(golden[:HeaderSize])
	f.Add([]byte{})
	f.Add(bytes.Repeat([]byte{0x4f}, 40))

	f.Fuzz(func(t *testing.T, data []byte) {
		fr, err := Decode(data)
		if err != nil {
			return // rejected input is fine; we only care that it did not panic
		}
		out, err := Encode(fr.Header, fr.Payload)
		if err != nil {
			t.Fatalf("Decode accepted %x but Encode refused: %v", data, err)
		}
		if !bytes.Equal(out, data) {
			t.Fatalf("round trip changed bytes\n in  %x\n out %x", data, out)
		}
	})
}
